mapper.sql:
WHERE 1=1
  AND p.id=#{query.productId}AND p.enabled=#{query.enabled}
  AND (CONVERT(p.code USING utf8mb4) LIKE CONCAT('%',#{query.keyword},'%') OR p.name LIKE CONCAT('%',#{query.keyword},'%') OR CONVERT(p.barcode USING utf8mb4)=#{query.keyword} OR CONVERT(i.batch_no USING utf8mb4) LIKE CONCAT('%',#{query.keyword},'%'))
  AND p.category_id=#{query.categoryId}
  AND p.enabled=1 AND p.can_sell=1 AND ()<=p.stock_lower_limit
   AND i.manages_expiry=1 AND i.batch_no IS NOT NULL AND i.stock_qty>0 AND o.status='IN_STOCK'
    AND DATEDIFF(i.expiry_date,#{today}) BETWEEN 0 AND p.near_expiry_daysAND i.expiry_date<#{today}
